#!/usr/bin/env node
const fs=require("fs"),p=require("path"),{execSync:e}=require("child_process");
const F={"src/commands/forfeit/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"forfeit\")\n    .setDescription(\"Log a 3-0 default win if a team fails to show (Management only)\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"winner\").setDescription(\"Winning team name\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Forfeit reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Management only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const winnerName = interaction.options.getString(\"winner\", true);\n    const reason = interaction.options.getString(\"reason\") ?? \"Team failed to show\";\n\n    try {\n      const match = await prisma.match.findUnique({\n        where: { id: matchId },\n        include: { homeTeam: true, awayTeam: true },\n      });\n      if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n\n      const isHomeWin = match.homeTeam.name.toLowerCase() === winnerName.toLowerCase();\n      const homeScore = isHomeWin ? 3 : 0;\n      const awayScore = isHomeWin ? 0 : 3;\n\n      await prisma.match.update({\n        where: { id: matchId },\n        data: { status: \"Forfeit\", homeScore, awayScore, forfeit: true, forfeitingTeam: isHomeWin ? \"away\" : \"home\" },\n      });\n\n      // Update standings as if finished\n      await matchService[\"updateTeamStatsAfterMatch\"]({\n        id: matchId, homeTeamId: match.homeTeamId, awayTeamId: match.awayTeamId,\n        homeScore, awayScore, seasonId: match.seasonId,\n      });\n\n      await predictionService.resolvePredictions(matchId);\n\n      if (interaction.guild) {\n        await newsService.announceMatchResult(interaction.client as ExtendedClient, {\n          guildId: interaction.guild.id,\n          homeTeam: match.homeTeam.name,\n          awayTeam: match.awayTeam.name,\n          homeScore, awayScore,\n          scorers: [\"Default win (forfeit)\"],\n          mvp: undefined,\n          matchId,\n        });\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚖️ Forfeit — Default Win\")\n        .setColor(\"#FF0000\")\n        .setDescription(`**${match.homeTeam.name}** ${homeScore} - ${awayScore} **${match.awayTeam.name}**`)\n        .addFields(\n          { name: \"✅ Winner\", value: isHomeWin ? match.homeTeam.name : match.awayTeam.name, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          { name: \"📊 Status\", value: \"⚖️ Forfeit\", inline: true },\n        )\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Forfeit Error]\", error);\n      await interaction.editReply({ content: \"❌ Failed to process forfeit.\" });\n    }\n  },\n};\nexport default command;","src/commands/lineup/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, Formation } from \"../../types/index.js\";\n\nconst FORMATIONS: { name: string; value: string }[] = [\n  { name: \"4-4-2\", value: \"4-4-2\" },\n  { name: \"4-3-3\", value: \"4-3-3\" },\n  { name: \"3-5-2\", value: \"3-5-2\" },\n  { name: \"4-2-3-1\", value: \"4-2-3-1\" },\n  { name: \"5-3-2\", value: \"5-3-2\" },\n  { name: \"4-1-4-1\", value: \"4-1-4-1\" },\n  { name: \"3-4-3\", value: \"3-4-3\" },\n];\n\nconst POSITIONS: Record<string, string[]> = {\n  \"4-4-2\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"LM\", \"CM\", \"CM\", \"RM\", \"ST\", \"ST\"],\n  \"4-3-3\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"CM\", \"CDM\", \"CM\", \"LW\", \"ST\", \"RW\"],\n  \"3-5-2\": [\"GK\", \"CB\", \"CB\", \"CB\", \"LM\", \"CM\", \"CDM\", \"CM\", \"RM\", \"ST\", \"ST\"],\n  \"4-2-3-1\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"CDM\", \"CDM\", \"LW\", \"CAM\", \"RW\", \"ST\"],\n  \"5-3-2\": [\"GK\", \"LWB\", \"CB\", \"CB\", \"CB\", \"RWB\", \"CM\", \"CM\", \"CM\", \"ST\", \"ST\"],\n  \"4-1-4-1\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"CDM\", \"LM\", \"CM\", \"CM\", \"RM\", \"ST\"],\n  \"3-4-3\": [\"GK\", \"CB\", \"CB\", \"CB\", \"LM\", \"CM\", \"CM\", \"RM\", \"LW\", \"ST\", \"RW\"],\n};\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"lineup\")\n    .setDescription(\"Submit a starting lineup for your team (Captains)\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"formation\").setDescription(\"Formation\").setRequired(true).addChoices(...FORMATIONS))\n    .addStringOption((o) => o.setName(\"starters\").setDescription(\"11 player @mentions comma-separated\").setRequired(true))\n    .addStringOption((o) => o.setName(\"bench\").setDescription(\"Bench players @mentions comma-separated\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const formation = interaction.options.getString(\"formation\", true) as Formation;\n    const startersRaw = interaction.options.getString(\"starters\", true);\n    const benchRaw = interaction.options.getString(\"bench\");\n\n    const match = await prisma.match.findUnique({ where: { id: matchId }, include: { homeTeam: true, awayTeam: true } });\n    if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n\n    // Check user is manager of one of the teams\n    const isHomeManager = match.homeTeam.managerId === interaction.user.id;\n    const isAwayManager = match.awayTeam.managerId === interaction.user.id;\n    if (!isHomeManager && !isAwayManager) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Not Your Team\", \"You must be the manager of a team in this match.\")] });\n      return;\n    }\n\n    const teamId = isHomeManager ? match.homeTeamId : match.awayTeamId;\n    const teamName = isHomeManager ? match.homeTeam.name : match.awayTeam.name;\n\n    // Parse starters\n    const starterIds = startersRaw.match(/<@(\\d+)>/g)?.map((m) => m.replace(/<@|>/g, \"\")) ?? [];\n    if (starterIds.length !== 11) {\n      await interaction.editReply({ content: \"❌ You must provide exactly 11 starters.\" });\n      return;\n    }\n\n    // Resolve player IDs\n    const playerMap = await prisma.player.findMany({ where: { discordId: { in: starterIds } }, include: { user: true } });\n    const benchIds = benchRaw ? benchRaw.match(/<@(\\d+)>/g)?.map((m) => m.replace(/<@|>/g, \"\")) ?? [] : [];\n    const benchPlayers = benchIds.length ? await prisma.player.findMany({ where: { discordId: { in: benchIds } } }) : [];\n\n    // Create lineup\n    const lineup = await prisma.lineup.create({\n      data: {\n        matchId, teamId, captainId: interaction.user.id, formation, isConfirmed: true,\n        players: {\n          create: [\n            ...playerMap.map((p, i) => ({\n              playerId: p.id,\n              position: POSITIONS[formation]?.[i] ?? `POS${i + 1}`,\n              isBench: false,\n              order: i,\n              matchId,\n            })),\n            ...benchPlayers.map((p, i) => ({\n              playerId: p.id,\n              position: \"SUB\",\n              isBench: true,\n              order: i + 20,\n              matchId,\n            })),\n          ],\n        },\n      },\n      include: { players: { include: { player: { include: { user: true } } } } },\n    });\n\n    const embed = new EmbedBuilder()\n      .setTitle(`📋 ${teamName} — Lineup Submitted`)\n      .setColor(\"#00AA00\")\n      .addFields(\n        { name: \"🎯 Formation\", value: formation, inline: true },\n        { name: \"👥 Starting XI\", value: lineup.players.filter((p) => !p.isBench).map((p) => `**${p.position}** — ${p.player.user.username}`).join(\"\\n\"), inline: false },\n      );\n    if (lineup.players.some((p) => p.isBench)) {\n      embed.addFields({ name: \"🔄 Bench\", value: lineup.players.filter((p) => p.isBench).map((p) => p.player.user.username).join(\", \"), inline: false });\n    }\n    embed.setFooter({ text: \"Legacy Football Championship • Lineup\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/motm/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder, ActionRowBuilder, StringSelectMenuBuilder, ComponentType } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"motm\")\n    .setDescription(\"Start a Man of the Match poll in the match thread\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n      include: {\n        homeTeam: { include: { players: { include: { user: true } } } },\n        awayTeam: { include: { players: { include: { user: true } } } },\n      },\n    });\n    if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n\n    const allPlayers = [...match.homeTeam.players, ...match.awayTeam.players];\n    if (allPlayers.length === 0) { await interaction.editReply({ content: \"❌ No players in this match.\" }); return; }\n\n    // Create poll\n    const poll = await prisma.motmPoll.create({ data: { matchId } });\n\n    const select = new StringSelectMenuBuilder()\n      .setCustomId(\"motm_vote\").setPlaceholder(\"Vote for Man of the Match...\")\n      .addOptions(\n        allPlayers.map((p) => ({\n          label: p.user.username,\n          value: p.id,\n          description: `${p.position} — ${p.team?.name ?? \"Unknown\"}`,\n          emoji: getPosEmoji(p.position),\n        }))\n      );\n\n    const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select);\n    const embed = new EmbedBuilder()\n      .setTitle(\"🏆 Man of the Match\")\n      .setColor(\"#FFD700\")\n      .setDescription(`**${match.homeTeam.name}** vs **${match.awayTeam.name}**\\n\\nVote for your MOTM below!`)\n      .setFooter({ text: \"Voting closes in 2 minutes • Legacy Football Championship\" }).setTimestamp();\n\n    const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n    const collector = reply.createMessageComponentCollector({ componentType: ComponentType.StringSelect, time: 120_000 });\n    const votes = new Map<string, number>();\n\n    collector.on(\"collect\", async (si) => {\n      const votedPlayerId = si.values[0];\n      // Check if already voted\n      const existing = await prisma.motmVote.findUnique({\n        where: { pollId_voterId: { pollId: poll.id, voterId: si.user.id } },\n      });\n      if (existing) {\n        await si.reply({ content: \"❌ You already voted!\", ephemeral: true });\n        return;\n      }\n      await prisma.motmVote.create({ data: { pollId: poll.id, playerId: votedPlayerId, voterId: si.user.id } });\n      votes.set(votedPlayerId, (votes.get(votedPlayerId) ?? 0) + 1);\n      await si.reply({ content: `✅ Vote counted for **${allPlayers.find((p) => p.id === votedPlayerId)?.user.username}**!`, ephemeral: true });\n    });\n\n    collector.on(\"end\", async () => {\n      // Find winner\n      let winnerId = \"\";\n      let maxVotes = 0;\n      for (const [pid, count] of votes) {\n        if (count > maxVotes) { maxVotes = count; winnerId = pid; }\n      }\n\n      if (winnerId) {\n        const winner = allPlayers.find((p) => p.id === winnerId);\n        await prisma.matchMvp.upsert({\n          where: { matchId },\n          update: { playerId: winnerId, reason: \"Man of the Match (Fan Vote)\" },\n          create: { matchId, playerId: winnerId, reason: \"Man of the Match (Fan Vote)\" },\n        });\n        await prisma.player.update({ where: { id: winnerId }, data: { mvps: { increment: 1 } } });\n\n        await prisma.motmPoll.update({ where: { id: poll.id }, data: { isActive: false } });\n\n        const resultEmbed = new EmbedBuilder()\n          .setTitle(`🏆 Man of the Match: ${winner?.user.username ?? \"Unknown\"}`)\n          .setColor(\"#FFD700\")\n          .setDescription(`**${winner?.user.username}** won with **${maxVotes}** vote${maxVotes > 1 ? \"s\" : \"\"}!`)\n          .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n\n        const disabledRow = ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n        disabledRow.components.forEach((c) => c.setDisabled(true));\n        await interaction.editReply({ embeds: [resultEmbed], components: [disabledRow] });\n      } else {\n        await interaction.editReply({ embeds: [embed.setDescription(\"No votes were cast.\")], components: [] });\n      }\n    });\n  },\n};\n\nfunction getPosEmoji(pos: string): string {\n  const map: Record<string, string> = { Goalkeeper: \"🧤\", Defender: \"🛡️\", Midfielder: \"🎯\", Forward: \"⚽\" };\n  return map[pos] ?? \"👤\";\n}\n\nexport default command;","src/commands/potw/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"potw\")\n    .setDescription(\"Award Player of the Week (Management only)\")\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"week\").setDescription(\"Week number\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Management only.\")] }); return;\n    }\n    const target = interaction.options.getUser(\"player\", true);\n    const week = interaction.options.getInteger(\"week\", true);\n    const reason = interaction.options.getString(\"reason\");\n    const season = await leagueService.getActiveSeason();\n    if (!season) { await interaction.editReply({ content: \"❌ No active season.\" }); return; }\n    const player = await prisma.player.findUnique({ where: { discordId: target.id }, include: { user: true, team: true } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n\n    const award = await prisma.weeklyAward.create({\n      data: { type: \"potw\", playerId: player.id, seasonId: season.id, weekNumber: week, reason },\n    });\n\n    if (interaction.guild) {\n      await newsService.announceAward(interaction.client as ExtendedClient, {\n        guildId: interaction.guild.id,\n        playerName: target.username,\n        awardType: `Player of the Week (GW${week})`,\n        season: season.name,\n        reason: reason ?? undefined,\n      });\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🌟 Player of the Week!\")\n      .setColor(\"#00AAFF\")\n      .setDescription(`**${target.username}** is the Player of the Week for **GW${week}**!`)\n      .addFields(\n        { name: \"👤 Player\", value: `<@${target.id}>`, inline: true },\n        { name: \"🏠 Club\", value: player.team?.name ?? \"Free Agent\", inline: true },\n        { name: \"⚽ Position\", value: player.position, inline: true },\n        { name: \"📝 Reason\", value: reason ?? \"Outstanding performance\", inline: false },\n      )\n      .setFooter({ text: `Week ${week} • Legacy Football Championship` }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/totw/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"totw\")\n    .setDescription(\"Award Team of the Week (Management only)\")\n    .addStringOption((o) => o.setName(\"team\").setDescription(\"Team name\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"week\").setDescription(\"Week number\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Management only.\")] }); return;\n    }\n    const teamName = interaction.options.getString(\"team\", true);\n    const week = interaction.options.getInteger(\"week\", true);\n    const reason = interaction.options.getString(\"reason\");\n    const season = await leagueService.getActiveSeason();\n    if (!season) { await interaction.editReply({ content: \"❌ No active season.\" }); return; }\n    const team = await prisma.team.findUnique({ where: { name: teamName }, include: { manager: true } });\n    if (!team) { await interaction.editReply({ content: \"❌ Team not found.\" }); return; }\n\n    await prisma.weeklyAward.create({\n      data: { type: \"totw\", teamId: team.id, seasonId: season.id, weekNumber: week, reason },\n    });\n\n    if (interaction.guild) {\n      await newsService.announceBroadcast(interaction.client as ExtendedClient, {\n        guildId: interaction.guild.id,\n        title: `🏅 Team of the Week (GW${week})`,\n        message: `**${team.name}** has been awarded **Team of the Week** for GW${week}!${reason ? `\\n\\n📝 ${reason}` : \"\"}`,\n        authorName: interaction.user.username,\n        color: \"#FFD700\",\n      });\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🏅 Team of the Week!\")\n      .setColor(\"#FFD700\")\n      .setDescription(`**${team.name}** is the Team of the Week for **GW${week}**!`)\n      .addFields(\n        { name: \"🏟️ Team\", value: team.name, inline: true },\n        { name: \"👤 Manager\", value: `<@${team.manager.discordId}>`, inline: true },\n        { name: \"📝 Reason\", value: reason ?? \"Outstanding team performance\", inline: false },\n      )\n      .setFooter({ text: `Week ${week} • Legacy Football Championship` }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/dispute/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ChannelType,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"dispute\")\n    .setDescription(\"Open a dispute ticket for admin review of a match incident\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"What are you disputing?\").setRequired(true))\n    .addStringOption((o) => o.setName(\"evidence\").setDescription(\"Link to clip/screenshot evidence\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n    const evidence = interaction.options.getString(\"evidence\");\n\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n      include: { homeTeam: true, awayTeam: true },\n    });\n    if (!match) {\n      await interaction.editReply({ content: \"❌ Match not found.\" });\n      return;\n    }\n\n    // Create dispute in DB\n    const dispute = await prisma.dispute.create({\n      data: {\n        matchId,\n        reporterId: interaction.user.id,\n        reason,\n        evidenceUrl: evidence ?? null,\n        status: \"Open\",\n      },\n    });\n\n    // Try to create a private thread\n    let threadInfo = \"\";\n    if (interaction.channel && interaction.channel.type === ChannelType.GuildText) {\n      try {\n        const thread = await interaction.channel.threads.create({\n          name: `🚩 Dispute: ${match.homeTeam.name} vs ${match.awayTeam.name}`,\n          reason: `Dispute ticket #${dispute.id.slice(0, 6)}`,\n          type: ChannelType.PrivateThread,\n        });\n        await thread.send({\n          content: `🚩 **New Dispute Opened**\\n👤 **Reporter:** <@${interaction.user.id}>\\n⚽ **Match:** ${match.homeTeam.name} vs ${match.awayTeam.name}\\n📝 **Reason:** ${reason}${evidence ? `\\n🔗 **Evidence:** ${evidence}` : \"\"}\\n\\n🛠️ **Admins:** Please review and use \\`/resolve\\` when done.`,\n        });\n        await prisma.dispute.update({\n          where: { id: dispute.id },\n          data: { ticketChannelId: thread.id },\n        });\n        threadInfo = `📝 Ticket created: ${thread}`;\n      } catch {\n        threadInfo = \"⚠️ Could not create ticket thread.\";\n      }\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🚩 Dispute Filed\")\n      .setColor(\"#FF6600\")\n      .setDescription(`Your dispute for **${match.homeTeam.name} vs ${match.awayTeam.name}** has been submitted.`)\n      .addFields(\n        { name: \"📝 Reason\", value: reason, inline: false },\n        { name: \"🔢 Dispute ID\", value: dispute.id.slice(0, 8), inline: true },\n        { name: \"📋 Status\", value: \"🟡 Under Review\", inline: true },\n      );\n    if (threadInfo) embed.addFields({ name: \"📎 Thread\", value: threadInfo, inline: false });\n\n    embed.setFooter({ text: \"Legacy Football Championship • Disputes\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/predict/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"predict\")\n    .setDescription(\"Predict the outcome of an upcoming match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"winner\").setDescription(\"Who wins?\").setRequired(true)\n      .addChoices(\n        { name: \"🏠 Home Team\", value: \"home\" },\n        { name: \"🚗 Away Team\", value: \"away\" },\n        { name: \"🤝 Draw\", value: \"draw\" },\n      )),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const winner = interaction.options.getString(\"winner\", true);\n\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n      include: { homeTeam: true, awayTeam: true },\n    });\n    if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n    if (match.status !== \"Scheduled\") { await interaction.editReply({ content: \"❌ This match has already started or finished.\" }); return; }\n\n    let predictedTeamId: string | undefined;\n    let draw = false;\n\n    if (winner === \"home\") predictedTeamId = match.homeTeamId;\n    else if (winner === \"away\") predictedTeamId = match.awayTeamId;\n    else draw = true;\n\n    await predictionService.predict({\n      matchId,\n      userId: interaction.user.id,\n      teamId: predictedTeamId,\n      draw,\n    });\n\n    const prediction = draw ? \"🤝 Draw\" : `${winner === \"home\" ? match.homeTeam.name : match.awayTeam.name} wins`;\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🔮 Prediction Submitted\")\n      .setColor(\"#FF6600\")\n      .setDescription(`You predicted: **${prediction}**`)\n      .addFields(\n        { name: \"⚽ Match\", value: `${match.homeTeam.name} vs ${match.awayTeam.name}`, inline: false },\n        { name: \"🎯 Your Pick\", value: prediction, inline: true },\n        { name: \"💰 Reward\", value: \"**3 pts** for correct prediction\", inline: true },\n      )\n      .setFooter({ text: \"Legacy Football Championship • Predictions\" }).setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/dashboard/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  ButtonBuilder,\n  ButtonStyle,\n  ComponentType,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"dashboard\")\n    .setDescription(\"Your personal LFC control panel\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    await showDashboard(interaction, \"overview\");\n  },\n};\n\nasync function showDashboard(interaction: CommandInteraction, tab: string) {\n  const userId = interaction.user.id;\n  const player = await playerService.getPlayer(userId);\n\n  if (!player) {\n    await interaction.editReply({ content: \"❌ You're not registered as an LFC player yet. Get offered a contract first!\" });\n    return;\n  }\n\n  let embed: EmbedBuilder;\n\n  switch (tab) {\n    case \"contract\": {\n      const contract = await contractService.getActiveContract(player.id);\n      embed = new EmbedBuilder()\n        .setTitle(\"📝 My Contract\")\n        .setColor(\"#00AA00\")\n        .setDescription(contract\n          ? `**Club:** ${contract.team.name}\\n**Role:** ${contract.roleInTeam ?? \"Starter\"}\\n**Signed:** <t:${Math.floor(contract.signedAt.getTime() / 1000)}:R>`\n          : \"No active contract. You're a free agent.\")\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    case \"stats\": {\n      const activeStat = player.seasonStats.find((s) => s.season.isActive);\n      embed = new EmbedBuilder()\n        .setTitle(\"📊 My Stats\")\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"📈 This Season\", value: activeStat\n            ? `⚽ ${activeStat.goals}G | 🎯 ${activeStat.assists}A | 🧤 ${activeStat.saves}S | 🏆 ${activeStat.mvps}MVP\\n📋 ${activeStat.appearances}Apps | 🧹 ${activeStat.cleanSheets}CS`\n            : \"No active season.\", inline: false },\n          { name: \"🏆 Career\", value: `⚽ ${player.goals}G | 🎯 ${player.assists}A | 🧤 ${player.saves}S | 🏆 ${player.mvps}MVP\\n📋 ${player.appearances}Apps | 🏅 ${player.trophies}Trophies`, inline: false },\n        )\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    case \"predictions\": {\n      const predStats = await predictionService.getUserStats(userId);\n      embed = new EmbedBuilder()\n        .setTitle(\"🔮 My Predictions\")\n        .setColor(\"#FF6600\")\n        .addFields(\n          { name: \"📊 Record\", value: `✅ ${predStats.correct} correct | ❌ ${predStats.total - predStats.correct} wrong | 📊 ${predStats.accuracy}% accuracy`, inline: false },\n          { name: \"📋 Recent Picks\", value: predStats.predictions.slice(0, 5).map((p) =>\n            `${p.match.homeTeam.name} vs ${p.match.awayTeam.name}: ${p.predictedDraw ? \"🤝 Draw\" : p.predictedTeamId === p.match.homeTeamId ? `🏠 ${p.match.homeTeam.name}` : `🚗 ${p.match.awayTeam.name}`}${p.resolved ? p.points > 0 ? \" ✅\" : \" ❌\" : \" ⏳\"}`\n          ).join(\"\\n\") || \"No predictions yet.\", inline: false },\n        )\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    default: {\n      const contract = await contractService.getActiveContract(player.id);\n      const upcomingMatches = contract\n        ? await prisma.match.findMany({\n            where: {\n              OR: [{ homeTeamId: contract.teamId }, { awayTeamId: contract.teamId }],\n              status: \"Scheduled\",\n            },\n            include: { homeTeam: true, awayTeam: true },\n            take: 3,\n          })\n        : [];\n\n      embed = new EmbedBuilder()\n        .setTitle(`👋 Welcome, ${interaction.user.username}`)\n        .setThumbnail(interaction.user.displayAvatarURL())\n        .setColor(\"#00AA00\")\n        .setDescription(`**LFC ID:** ${player.lfcId}\\n**Club:** ${player.team?.name ?? \"🆓 Free Agent\"}\\n**Position:** ${player.position} | **Region:** ${player.region}`)\n        .addFields(\n          { name: \"⚽ Season Stats\", value: `⚽${player.goals}G 🎯${player.assists}A 🏆${player.mvps}MVP`, inline: true },\n          { name: \"🏆 Trophies\", value: `${player.trophies}`, inline: true },\n          { name: \"📋 Appearances\", value: `${player.appearances}`, inline: true },\n        );\n\n      if (upcomingMatches.length) {\n        embed.addFields({\n          name: \"📅 Upcoming Fixtures\",\n          value: upcomingMatches.map((m) => `• ${m.homeTeam.name} vs ${m.awayTeam.name}`).join(\"\\n\"),\n          inline: false,\n        });\n      }\n    }\n  }\n\n  const row = new ActionRowBuilder<ButtonBuilder>().addComponents(\n    new ButtonBuilder().setCustomId(\"dash_overview\").setLabel(\"🏠 Home\").setStyle(tab === \"overview\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n    new ButtonBuilder().setCustomId(\"dash_stats\").setLabel(\"📊 Stats\").setStyle(tab === \"stats\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n    new ButtonBuilder().setCustomId(\"dash_contract\").setLabel(\"📝 Contract\").setStyle(tab === \"contract\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n    new ButtonBuilder().setCustomId(\"dash_predictions\").setLabel(\"🔮 Predictions\").setStyle(tab === \"predictions\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n  );\n\n  const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n  const collector = reply.createMessageComponentCollector({ componentType: ComponentType.Button, time: 120_000 });\n  collector.on(\"collect\", async (bi) => {\n    if (bi.user.id !== interaction.user.id) { await bi.reply({ content: \"❌ Not your dashboard.\", ephemeral: true }); return; }\n    await bi.deferUpdate();\n    const newTab = bi.customId.replace(\"dash_\", \"\");\n    await showDashboard(bi as unknown as CommandInteraction, newTab);\n  });\n  collector.on(\"end\", async () => {\n    const dr = ActionRowBuilder.from<ButtonBuilder>(row);\n    dr.components.forEach((c) => c.setDisabled(true));\n    await interaction.editReply({ components: [dr] }).catch(() => {});\n  });\n}\n\nexport default command;","src/commands/card/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  AttachmentBuilder,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\nimport { createCanvas, loadImage, registerFont } from \"canvas\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nconst POSITION_COLORS: Record<string, string> = {\n  Goalkeeper: \"#FFD700\",\n  Defender: \"#00AAFF\",\n  Midfielder: \"#00CC66\",\n  Forward: \"#FF4444\",\n};\n\nconst RARITY_COLORS: Record<string, string> = {\n  Common: \"#888888\",\n  Rare: \"#22AAFF\",\n  \"Epic\": \"#AA44FF\",\n  Legendary: \"#FFAA00\",\n};\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"card\")\n    .setDescription(\"Generate an EA FC style player card\")\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player\").setRequired(true)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const target = interaction.options.getUser(\"player\", true);\n    const player = await prisma.player.findUnique({\n      where: { discordId: target.id },\n      include: { user: true, team: true },\n    });\n    if (!player) {\n      await interaction.editReply({ content: \"❌ Player not registered.\" });\n      return;\n    }\n\n    try {\n      const width = 400;\n      const height = 560;\n      const canvas = createCanvas(width, height);\n      const ctx = canvas.getContext(\"2d\");\n\n      // Background gradient\n      const bgColor = POSITION_COLORS[player.position] ?? \"#00AA00\";\n      const grad = ctx.createLinearGradient(0, 0, width, height);\n      grad.addColorStop(0, bgColor);\n      grad.addColorStop(0.4, \"#1a1a2e\");\n      grad.addColorStop(1, \"#0f0f1a\");\n      ctx.fillStyle = grad;\n      ctx.fillRect(0, 0, width, height);\n\n      // Card border\n      ctx.strokeStyle = bgColor;\n      ctx.lineWidth = 3;\n      ctx.strokeRect(5, 5, width - 10, height - 10);\n\n      // Top accent bar\n      ctx.fillStyle = bgColor;\n      ctx.fillRect(10, 10, width - 20, 4);\n\n      // Rating circle\n      const rating = Math.min(99, Math.max(60, player.goals * 3 + player.appearances + 60));\n      ctx.beginPath();\n      ctx.arc(80, 100, 40, 0, Math.PI * 2);\n      ctx.fillStyle = \"rgba(0,0,0,0.5)\";\n      ctx.fill();\n      ctx.strokeStyle = bgColor;\n      ctx.lineWidth = 3;\n      ctx.stroke();\n\n      ctx.fillStyle = \"#FFFFFF\";\n      ctx.font = \"bold 36px Arial\";\n      ctx.textAlign = \"center\";\n      ctx.fillText(`${rating}`, 80, 112);\n\n      // Position label\n      ctx.font = \"bold 18px Arial\";\n      ctx.fillStyle = bgColor;\n      ctx.textAlign = \"left\";\n      const posAbbr: Record<string, string> = {\n        Goalkeeper: \"GK\", Defender: \"DEF\", Midfielder: \"MID\", Forward: \"FWD\",\n      };\n      ctx.fillText(posAbbr[player.position] ?? \"LFC\", 140, 85);\n\n      // Player name\n      ctx.fillStyle = \"#FFFFFF\";\n      ctx.font = \"bold 24px Arial\";\n      ctx.fillText(target.username.length > 14 ? target.username.slice(0, 14) + \"...\" : target.username, 140, 115);\n\n      // Stats\n      const stats = [\n        { label: \"GOALS\", value: player.goals, max: 50 },\n        { label: \"ASSISTS\", value: player.assists, max: 50 },\n        { label: \"APPS\", value: player.appearances, max: 100 },\n        { label: \"MVP\", value: player.mvps, max: 20 },\n      ];\n\n      ctx.textAlign = \"left\";\n      stats.forEach((stat, i) => {\n        const y = 160 + i * 55;\n        ctx.fillStyle = \"#AAAAAA\";\n        ctx.font = \"12px Arial\";\n        ctx.fillText(stat.label, 30, y);\n\n        ctx.fillStyle = \"#FFFFFF\";\n        ctx.font = \"bold 28px Arial\";\n        ctx.fillText(`${stat.value}`, 30, y + 25);\n\n        // Stat bar background\n        ctx.fillStyle = \"rgba(255,255,255,0.1)\";\n        ctx.fillRect(120, y + 10, 220, 8);\n        // Stat bar fill\n        const pct = Math.min(1, stat.value / stat.max);\n        const barGrad = ctx.createLinearGradient(120, 0, 340, 0);\n        barGrad.addColorStop(0, bgColor);\n        barGrad.addColorStop(1, \"#FFFFFF\");\n        ctx.fillStyle = barGrad;\n        ctx.fillRect(120, y + 10, 220 * pct, 8);\n      });\n\n      // Club badge area\n      if (player.team) {\n        ctx.fillStyle = \"rgba(255,255,255,0.1)\";\n        ctx.fillRect(30, 400, width - 60, 50);\n        ctx.fillStyle = bgColor;\n        ctx.font = \"bold 16px Arial\";\n        ctx.textAlign = \"center\";\n        ctx.fillText(player.team.name, width / 2, 430);\n      }\n\n      // LFC ID & footer\n      ctx.fillStyle = \"rgba(255,255,255,0.4)\";\n      ctx.font = \"11px Arial\";\n      ctx.textAlign = \"center\";\n      ctx.fillText(`LFC ID: ${player.lfcId}`, width / 2, 480);\n\n      ctx.fillStyle = \"rgba(255,255,255,0.2)\";\n      ctx.font = \"10px Arial\";\n      ctx.fillText(\"LEGACY FOOTBALL CHAMPIONSHIP\", width / 2, height - 30);\n\n      // Bottom accent bar\n      ctx.fillStyle = bgColor;\n      ctx.fillRect(10, height - 14, width - 20, 4);\n\n      // Convert to buffer\n      const buffer = canvas.toBuffer(\"image/png\");\n      const attachment = new AttachmentBuilder(buffer, { name: `${target.username}-card.png` });\n\n      await interaction.editReply({\n        content: `🏆 **${target.username}** — EA FC Style Card`,\n        files: [attachment],\n      });\n    } catch (error) {\n      console.error(\"[Card Error]\", error);\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Card Generation Failed\", \"Could not generate player card.\")],\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/setup.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  PermissionFlagsBits,\n} from \"discord.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed, createSuccessEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"setup\")\n    .setDescription(\"Set up the LFC bot in this server (Founder only)\")\n    .setDefaultMemberPermissions(PermissionFlagsBits.Administrator),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder)) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only the **Founder** can run setup.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const guild = interaction.guild;\n    if (!guild) {\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Error\", \"This command must be used in a server.\")],\n      });\n      return;\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"✅ LFC Bot Setup Complete\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        \"Legacy Football Championship bot has been configured for this server!\"\n      )\n      .addFields(\n        {\n          name: \"📋 Required Roles\",\n          value: [\n            \"Make sure these roles exist in your server:\",\n            \"• **Founder** — Top-level admin access\",\n            \"• **League Management** — League operations\",\n            \"• **Moderator** — General moderation\",\n            \"• **Referee** — Match officiating\",\n          ].join(\"\\n\"),\n          inline: false,\n        },\n        {\n          name: \"⚙️ Getting Started\",\n          value: [\n            \"1. `/season start` — Begin a new season\",\n            \"2. `/team create` — Register teams\",\n            \"3. `/match create` — Schedule matches\",\n            \"4. `/match start` — Begin a match\",\n            \"5. `/match report` — Record events\",\n            \"6. `/match finish` — End the match\",\n          ].join(\"\\n\"),\n          inline: false,\n        },\n        {\n          name: \"📖 Need Help?\",\n          value: \"Use `/` to browse all available commands.\",\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/admin/warn.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { adminService } from \"../../services/adminService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed, formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"warn\")\n    .setDescription(\"Warn a user for misconduct (Staff only)\")\n    .addUserOption((opt) =>\n      opt\n        .setName(\"user\")\n        .setDescription(\"User to warn\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"reason\")\n        .setDescription(\"Reason for the warning\")\n        .setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Moderator)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder**, **League Management**, or **Moderator** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"user\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n\n    try {\n      await adminService.warnUser(targetUser.id, reason, interaction.user.id);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚠️ Warning Issued\")\n        .setColor(\"#FFAA00\")\n        .addFields(\n          { name: \"👤 User\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          { name: \"👮‍♂️ Issued By\", value: `<@${interaction.user.id}>`, inline: true }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n\n      // Try to DM the warned user\n      try {\n        const dmEmbed = new EmbedBuilder()\n          .setTitle(\"⚠️ You have received a warning\")\n          .setColor(\"#FFAA00\")\n          .addFields(\n            { name: \"Server\", value: interaction.guild?.name ?? \"LFC\", inline: true },\n            { name: \"Reason\", value: reason, inline: false }\n          )\n          .setFooter({ text: \"Legacy Football Championship\" })\n          .setTimestamp();\n\n        await targetUser.send({ embeds: [dmEmbed] });\n      } catch {\n        // User may have DMs disabled, that's fine\n      }\n    } catch (error) {\n      console.error(\"[Warn Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while issuing the warning.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/suspend.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { adminService } from \"../../services/adminService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"suspend\")\n    .setDescription(\"Suspend a user from the league (Management only)\")\n    .addUserOption((opt) =>\n      opt\n        .setName(\"user\")\n        .setDescription(\"User to suspend\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"reason\")\n        .setDescription(\"Reason for the suspension\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"duration\")\n        .setDescription(\"Suspension duration (e.g. 7d, 30d, permanent)\")\n        .setRequired(false)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"user\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n    const duration = interaction.options.getString(\"duration\");\n\n    try {\n      // Parse duration\n      let expiresAt: Date | undefined;\n      if (duration && duration !== \"permanent\") {\n        const match = duration.match(/^(\\d+)(d|h|m)$/);\n        if (match) {\n          const amount = parseInt(match[1]);\n          const unit = match[2];\n          const now = new Date();\n          switch (unit) {\n            case \"m\":\n              expiresAt = new Date(now.getTime() + amount * 60000);\n              break;\n            case \"h\":\n              expiresAt = new Date(now.getTime() + amount * 3600000);\n              break;\n            case \"d\":\n              expiresAt = new Date(now.getTime() + amount * 86400000);\n              break;\n          }\n        }\n      }\n\n      await adminService.suspendUser(\n        targetUser.id,\n        reason,\n        interaction.user.id,\n        expiresAt\n      );\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🔒 User Suspended\")\n        .setColor(\"#FF0000\")\n        .addFields(\n          { name: \"👤 User\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          {\n            name: \"⏱ Duration\",\n            value: expiresAt ? `Until ${expiresAt.toLocaleDateString()}` : \"Permanent\",\n            inline: true,\n          },\n          {\n            name: \"👮‍♂️ Issued By\",\n            value: `<@${interaction.user.id}>`,\n            inline: true,\n          }\n        )\n        .setFooter({ text: \"Use /suspend again to extend | Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Suspend Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while suspending the user.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/blacklist.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { adminService } from \"../../services/adminService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"blacklist\")\n    .setDescription(\"Blacklist a user from the league (Founder only)\")\n    .addUserOption((opt) =>\n      opt\n        .setName(\"user\")\n        .setDescription(\"User to blacklist\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"reason\")\n        .setDescription(\"Reason for blacklisting\")\n        .setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    if (!hasRole(interaction.member as never, RoleType.Founder)) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only the **Founder** can blacklist users.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"user\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n\n    try {\n      const isBlacklisted = await adminService.isBlacklisted(targetUser.id);\n      if (isBlacklisted) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Already Blacklisted\",\n              `${targetUser.username} is already blacklisted.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      await adminService.blacklistUser(targetUser.id, reason, interaction.user.id);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🚫 User Blacklisted\")\n        .setColor(\"#000000\")\n        .addFields(\n          { name: \"👤 User\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          { name: \"👮‍♂️ Issued By\", value: `<@${interaction.user.id}>`, inline: true }\n        )\n        .setFooter({ text: \"This action is irreversible | Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Blacklist Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while blacklisting the user.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/season.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"season\")\n    .setDescription(\"Season management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"start\")\n        .setDescription(\"Start a new season (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Season name (e.g. Season 3)\")\n            .setRequired(true)\n        )\n    )\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"end\")\n        .setDescription(\"End the current active season (Management only)\")\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const subcommand = interaction.options.getSubcommand();\n    const client = interaction.client as ExtendedClient;\n\n    try {\n      if (subcommand === \"start\") {\n        await handleSeasonStart(interaction, client);\n      } else if (subcommand === \"end\") {\n        await handleSeasonEnd(interaction, client);\n      }\n    } catch (error) {\n      console.error(\"[Season Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred managing the season.\",\n      });\n    }\n  },\n};\n\nasync function handleSeasonStart(interaction: CommandInteraction, client: ExtendedClient) {\n  const name = interaction.options.getString(\"name\", true);\n\n  // Check for existing active season\n  const active = await leagueService.getActiveSeason();\n  if (active) {\n    await interaction.editReply({\n      embeds: [\n        createErrorEmbed(\n          \"❌ Season Already Active\",\n          `**${active.name}** is already active. End it first with \\`/season end\\`.`\n        ),\n      ],\n    });\n    return;\n  }\n\n  const season = await leagueService.createSeason(name);\n  await leagueService.initializeSeasonStats(season.id);\n  await leagueService.initializePlayerSeasonStats(season.id);\n\n  // ── Auto-post season start news ──\n  try {\n    if (interaction.guild) {\n      const teams = await teamService.listTeams();\n      await newsService.announceSeasonStart(client, {\n        guildId: interaction.guild.id,\n        seasonName: season.name,\n        teamCount: teams.length,\n      });\n    }\n  } catch (newsError) {\n    console.error(\"[Season News Error]\", newsError);\n  }\n\n  const embed = new EmbedBuilder()\n    .setTitle(\"📅 New Season Started!\")\n    .setColor(\"#00AA00\")\n    .setDescription(`**${season.name}** is now active!`)\n    .addFields(\n      { name: \"📋 Season\", value: season.name, inline: true },\n      { name: \"🎯 Status\", value: \"🟢 Active\", inline: true },\n      {\n        name: \"✅ What's Next?\",\n        value: [\n          \"1. Make sure all teams are registered with `/team create`\",\n          \"2. Schedule matches with `/match create`\",\n          \"3. Use `/standings` to track the league table\",\n        ].join(\"\\n\"),\n        inline: false,\n      }\n    )\n    .setFooter({ text: \"Legacy Football Championship\" })\n    .setTimestamp();\n\n  await interaction.editReply({ embeds: [embed] });\n}\n\nasync function handleSeasonEnd(interaction: CommandInteraction, client: ExtendedClient) {\n  const active = await leagueService.getActiveSeason();\n  if (!active) {\n    await interaction.editReply({\n      embeds: [createErrorEmbed(\"❌ No Active Season\", \"There is no active season to end.\")],\n    });\n    return;\n  }\n\n  // Get final standings\n  const standings = await leagueService.getStandings(active.id);\n  const champion = standings[0];\n\n  const ended = await leagueService.endActiveSeason();\n\n  // ── Auto-post season end news ──\n  try {\n    if (interaction.guild) {\n      await newsService.announceSeasonEnd(client, {\n        guildId: interaction.guild.id,\n        seasonName: active.name,\n        championName: champion?.teamName,\n        championPoints: champion?.points,\n      });\n    }\n  } catch (newsError) {\n    console.error(\"[Season News Error]\", newsError);\n  }\n\n  const embed = new EmbedBuilder()\n    .setTitle(\"🏆 Season Ended!\")\n    .setColor(\"#FFD700\")\n    .setDescription(`**${active.name}** has come to a close!`);\n\n  if (champion) {\n    embed.addFields({\n      name: \"👑 Champions\",\n      value: `**${champion.teamName}** — ${champion.points}pts (${champion.wins}W / ${champion.draws}D / ${champion.losses}L)`,\n      inline: false,\n    });\n  }\n\n  embed\n    .addFields(\n      { name: \"📋 Season\", value: active.name, inline: true },\n      { name: \"✅ Status\", value: \"🔴 Ended\", inline: true },\n      {\n        name: \"🎯 Next Steps\",\n        value: \"Use `/award give` to distribute season awards, then `/season start` to begin a new season.\",\n        inline: false,\n      }\n    )\n    .setFooter({ text: \"Legacy Football Championship\" })\n    .setTimestamp();\n\n  await interaction.editReply({ embeds: [embed] });\n}\n\nexport default command;","src/commands/award/give.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, AwardType, ExtendedClient } from \"../../types/index.js\";\n\nconst AWARD_TYPES: AwardType[] = [\n  \"Golden Boot\",\n  \"Golden Boy\",\n  \"Best Playmaker\",\n  \"Player of the Season\",\n  \"Team of the Season\",\n  \"Manager of the Season\",\n];\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"award\")\n    .setDescription(\"Award management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"give\")\n        .setDescription(\"Give an award to a player (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"type\")\n            .setDescription(\"Award type\")\n            .setRequired(true)\n            .addChoices(\n              ...AWARD_TYPES.map((t) => ({ name: t, value: t }))\n            )\n        )\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"Player to award\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"reason\")\n            .setDescription(\"Reason for the award\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can give awards.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const awardType = interaction.options.getString(\"type\", true) as AwardType;\n    const targetUser = interaction.options.getUser(\"player\", true);\n    const reason = interaction.options.getString(\"reason\");\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n\n      if (!player) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Player Not Found\",\n              `${targetUser.username} is not registered as an LFC player.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      const activeSeason = await leagueService.getActiveSeason();\n\n      if (!activeSeason) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ No Active Season\",\n              \"Start a season before giving awards.\"\n            ),\n          ],\n        });\n        return;\n      }\n\n      // Check if player already has this award this season\n      const existingAward = await prisma.award.findUnique({\n        where: {\n          playerId_seasonId_type: {\n            playerId: player.id,\n            seasonId: activeSeason.id,\n            type: awardType,\n          },\n        },\n      });\n\n      if (existingAward) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Award Already Given\",\n              `${targetUser.username} already received **${awardType}** in ${activeSeason.name}.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      const award = await prisma.award.create({\n        data: {\n          type: awardType,\n          playerId: player.id,\n          seasonId: activeSeason.id,\n          reason,\n        },\n        include: {\n          player: { include: { user: true } },\n          season: true,\n        },\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(`🏅 Award Given!`)\n        .setColor(\"#FFD700\")\n        .setDescription(\n          `**${award.player.user.username}** has been awarded **${award.type}**!`\n        )\n        .addFields(\n          { name: \"🏅 Award\", value: award.type, inline: true },\n          { name: \"📅 Season\", value: award.season.name, inline: true },\n          {\n            name: \"📝 Reason\",\n            value: award.reason ?? \"Outstanding performance\",\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      // Increment trophies counter\n      await prisma.player.update({\n        where: { id: player.id },\n        data: { trophies: { increment: 1 } },\n      });\n\n      // ── Auto-post award news ──\n      try {\n        if (interaction.guild) {\n          await newsService.announceAward(\n            interaction.client as ExtendedClient,\n            {\n              guildId: interaction.guild.id,\n              playerName: targetUser.username,\n              awardType: award.type,\n              season: award.season.name,\n              reason: award.reason ?? undefined,\n            }\n          );\n        }\n      } catch (newsError) {\n        console.error(\"[Award News Error]\", newsError);\n        // Non-fatal\n      }\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Award Give Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while giving the award.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/league/standings.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"standings\")\n    .setDescription(\"View the current league table\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const activeSeason = await leagueService.getActiveSeason();\n\n      if (!activeSeason) {\n        await interaction.editReply({\n          content: \"❌ No active season. Use `/season start` to begin a season.\",\n        });\n        return;\n      }\n\n      const standings = await leagueService.getStandings(activeSeason.id);\n\n      const embed = new EmbedBuilder()\n        .setTitle(`🏆 ${activeSeason.name} — League Standings`)\n        .setColor(\"#00AA00\")\n        .setDescription(\n          standings.length > 0\n            ? standings\n                .map(\n                  (s) =>\n                    `**${s.position}.** ${getPositionEmoji(s.position)} **${s.teamName}**` +\n                    `\\n    ${s.played}PL | ${s.wins}W | ${s.draws}D | ${s.losses}L` +\n                    ` | GF:${s.goalsFor} GA:${s.goalsAgainst} GD:${s.goalDifference >= 0 ? \"+\" : \"\"}${s.goalDifference}` +\n                    ` | **${s.points}pts**`\n                )\n                .join(\"\\n\\n\")\n            : \"No standings data yet. Start the season and play matches!\"\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Standings Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching standings.\",\n      });\n    }\n  },\n};\n\nfunction getPositionEmoji(pos: number): string {\n  switch (pos) {\n    case 1:\n      return \"🥇\";\n    case 2:\n      return \"🥈\";\n    case 3:\n      return \"🥉\";\n    default:\n      return \"#\";\n  }\n}\n\nexport default command;","src/commands/league/fixtures.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"fixtures\")\n    .setDescription(\"View upcoming match fixtures\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const activeSeason = await leagueService.getActiveSeason();\n      const fixtures = await matchService.getUpcomingFixtures(10);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📅 Upcoming Fixtures\")\n        .setColor(\"#00AA00\");\n\n      if (fixtures.length > 0) {\n        for (const match of fixtures) {\n          embed.addFields({\n            name: `${match.homeTeam.name} vs ${match.awayTeam.name}`,\n            value: [\n              `📅 **Date:** ${formatDate(match.matchDate)}`,\n              `📊 **Season:** ${match.season.name}`,\n              match.refereeId ? `👨‍⚖️ **Referee:** <@${match.refereeId}>` : null,\n            ]\n              .filter(Boolean)\n              .join(\"\\n\"),\n            inline: false,\n          });\n        }\n      } else {\n        embed.setDescription(\n          activeSeason\n            ? \"No upcoming fixtures scheduled.\"\n            : \"No active season. Start a season first!\"\n        );\n      }\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Fixtures Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching fixtures.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/league/results.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"results\")\n    .setDescription(\"View recent match results\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const results = await matchService.getRecentResults(10);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📋 Recent Results\")\n        .setColor(\"#00AA00\");\n\n      if (results.length > 0) {\n        for (const match of results) {\n          const homeWin = match.homeScore > match.awayScore;\n          const awayWin = match.awayScore > match.homeScore;\n          const scoreEmoji = homeWin ? \"🏠\" : awayWin ? \"🚗\" : \"🤝\";\n\n          // Get scorers if available\n          const scorers = match.goals\n            .slice(0, 3)\n            .map((g) => g.player.user.username)\n            .join(\", \");\n\n          // Get MVP if available\n          const mvp = match.mvps[0];\n\n          embed.addFields({\n            name: `${scoreEmoji} ${match.homeTeam.name} ${match.homeScore} - ${match.awayScore} ${match.awayTeam.name}`,\n            value: [\n              `📅 ${match.matchDate ? new Date(match.matchDate).toLocaleDateString() : \"N/A\"}`,\n              scorers ? `⚽ **Scorers:** ${scorers}` : null,\n              mvp ? `🏆 **MVP:** ${mvp.player.user.username}` : null,\n            ]\n              .filter(Boolean)\n              .join(\"\\n\"),\n            inline: false,\n          });\n        }\n      } else {\n        embed.setDescription(\"No match results yet.\");\n      }\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Results Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching results.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/league/history.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"history\")\n    .setDescription(\"View match history between two teams\")\n    .addStringOption((opt) =>\n      opt\n        .setName(\"team1\")\n        .setDescription(\"First team name\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"team2\")\n        .setDescription(\"Second team name\")\n        .setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const team1Name = interaction.options.getString(\"team1\", true);\n    const team2Name = interaction.options.getString(\"team2\", true);\n\n    try {\n      const teamService = await import(\"../../services/teamService.js\").then(\n        (m) => m.teamService\n      );\n\n      const team1 = await teamService.getTeamByName(team1Name);\n      const team2 = await teamService.getTeamByName(team2Name);\n\n      if (!team1 || !team2) {\n        await interaction.editReply({\n          content: \"❌ One or both teams not found.\",\n        });\n        return;\n      }\n\n      const matches = await matchService.getTeamMatches(team1.id);\n      const headToHead = matches.filter(\n        (m) =>\n          (m.homeTeamId === team1.id && m.awayTeamId === team2.id) ||\n          (m.homeTeamId === team2.id && m.awayTeamId === team1.id)\n      );\n\n      if (headToHead.length === 0) {\n        await interaction.editReply({\n          content: `📋 **${team1.name}** and **${team2.name}** have no match history.`,\n        });\n        return;\n      }\n\n      // Calculate head-to-head record\n      let team1Wins = 0;\n      let team2Wins = 0;\n      let draws = 0;\n      let team1Goals = 0;\n      let team2Goals = 0;\n\n      for (const m of headToHead) {\n        if (m.status !== \"Finished\") continue;\n        const isTeam1Home = m.homeTeamId === team1.id;\n        const t1Score = isTeam1Home ? m.homeScore : m.awayScore;\n        const t2Score = isTeam1Home ? m.awayScore : m.homeScore;\n\n        team1Goals += t1Score;\n        team2Goals += t2Score;\n\n        if (t1Score > t2Score) team1Wins++;\n        else if (t2Score > t1Score) team2Wins++;\n        else draws++;\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(`📊 Head-to-Head: ${team1.name} vs ${team2.name}`)\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: `🏠 ${team1.name}`,\n            value: `${team1Wins} wins | ${team1Goals} goals`,\n            inline: true,\n          },\n          { name: \"🤝 Draws\", value: `${draws}`, inline: true },\n          {\n            name: `🚗 ${team2.name}`,\n            value: `${team2Wins} wins | ${team2Goals} goals`,\n            inline: true,\n          },\n          {\n            name: `📋 Last ${Math.min(headToHead.length, 5)} Meetings`,\n            value: headToHead\n              .slice(0, 5)\n              .map((m) => {\n                const isTeam1Home = m.homeTeamId === team1.id;\n                const t1Score = isTeam1Home ? m.homeScore : m.awayScore;\n                const t2Score = isTeam1Home ? m.awayScore : m.homeScore;\n                return `${formatDate(m.matchDate)}: ${team1.name} ${t1Score} - ${t2Score} ${team2.name}`;\n              })\n              .join(\"\\n\"),\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[History Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching history.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/match/create.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed, formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"create\")\n        .setDescription(\"Schedule a new match (Management/Referee only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"home\")\n            .setDescription(\"Home team name\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"away\")\n            .setDescription(\"Away team name\")\n            .setRequired(true)\n        )\n        .addUserOption((opt) =>\n          opt\n            .setName(\"referee\")\n            .setDescription(\"Match referee\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder**, **League Management**, or **Referee** role to create matches.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const homeName = interaction.options.getString(\"home\", true);\n    const awayName = interaction.options.getString(\"away\", true);\n    const refereeUser = interaction.options.getUser(\"referee\");\n\n    try {\n      const homeTeam = await teamService.getTeamByName(homeName);\n      const awayTeam = await teamService.getTeamByName(awayName);\n\n      if (!homeTeam) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Team Not Found\", `Home team **${homeName}** not found.`)],\n        });\n        return;\n      }\n\n      if (!awayTeam) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Team Not Found\", `Away team **${awayName}** not found.`)],\n        });\n        return;\n      }\n\n      if (homeTeam.id === awayTeam.id) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Invalid Match\", \"A team cannot play against itself.\")],\n        });\n        return;\n      }\n\n      const activeSeason = await leagueService.getActiveSeason();\n      if (!activeSeason) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ No Active Season\", \"Please start a season first using `/season start`.\")],\n        });\n        return;\n      }\n\n      const match = await matchService.createMatch({\n        homeTeamId: homeTeam.id,\n        awayTeamId: awayTeam.id,\n        seasonId: activeSeason.id,\n        refereeId: refereeUser?.id,\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚽ Match Scheduled\")\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"🏠 Home\", value: homeTeam.name, inline: true },\n          { name: \"🆚\", value: \"vs\", inline: true },\n          { name: \"🚗 Away\", value: awayTeam.name, inline: true },\n          { name: \"📅 Season\", value: activeSeason.name, inline: true },\n          { name: \"🔢 Match ID\", value: match.id.slice(0, 8), inline: true },\n          { name: \"👨‍⚖️ Referee\", value: refereeUser ? `<@${refereeUser.id}>` : \"TBD\", inline: true },\n          { name: \"📋 Status\", value: \"🟢 Scheduled\", inline: false }\n        )\n        .setFooter({ text: \"Use /match start to begin the match\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Match Create Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while creating the match.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/match/start.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"start\")\n        .setDescription(\"Start a scheduled match\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"match_id\")\n            .setDescription(\"Match ID to start\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only staff can start matches.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n\n    try {\n      const match = await matchService.startMatch(matchId);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚽ Match Started!\")\n        .setColor(\"#FFAA00\")\n        .setDescription(\n          `**${match.homeTeamId}** vs **${match.awayTeamId}** is now **LIVE**!`\n        )\n        .addFields(\n          { name: \"🟢 Status\", value: \"Live\", inline: true },\n          { name: \"🔢 Match ID\", value: match.id.slice(0, 8), inline: true }\n        )\n        .setFooter({ text: \"Use /match report to record goals, assists, and cards\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Match Start Error]\", error);\n      await interaction.editReply({\n        content: \"❌ Match not found or could not be started.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/match/report.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"report\")\n        .setDescription(\"Report match events (goal, assist, card, MVP)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"match_id\")\n            .setDescription(\"Match ID\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"event\")\n            .setDescription(\"Event type\")\n            .setRequired(true)\n            .addChoices(\n              { name: \"⚽ Goal\", value: \"goal\" },\n              { name: \"🎯 Assist\", value: \"assist\" },\n              { name: \"🟨 Yellow Card\", value: \"yellow\" },\n              { name: \"🟥 Red Card\", value: \"red\" },\n              { name: \"🏆 MVP\", value: \"mvp\" }\n            )\n        )\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"Player involved\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"minute\")\n            .setDescription(\"Minute of the event\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only staff can report match events.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const eventType = interaction.options.getString(\"event\", true);\n    const targetUser = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getString(\"minute\");\n    const minuteNum = minute ? parseInt(minute) : undefined;\n\n    // Note: In production, you'd import playerService to resolve the player ID\n    // For now we output the event as a logged message\n    const eventEmojis: Record<string, string> = {\n      goal: \"⚽\",\n      assist: \"🎯\",\n      yellow: \"🟨\",\n      red: \"🟥\",\n      mvp: \"🏆\",\n    };\n\n    const embed = new EmbedBuilder()\n      .setTitle(`${eventEmojis[eventType] ?? \"📋\"} Match Event Reported`)\n      .setColor(\"#00AA00\")\n      .addFields(\n        { name: \"🔢 Match ID\", value: matchId.slice(0, 8), inline: true },\n        { name: \"📋 Event\", value: eventType.toUpperCase(), inline: true },\n        { name: \"👤 Player\", value: `<@${targetUser.id}>`, inline: true },\n        { name: \"⏱ Minute\", value: minute ?? \"N/A\", inline: true },\n        { name: \"📝 Reported By\", value: `<@${interaction.user.id}>`, inline: true }\n      )\n      .setFooter({ text: \"Use /match finish to end the match\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/match/finish.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"finish\")\n        .setDescription(\"Finish a match with the final score\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"match_id\")\n            .setDescription(\"Match ID to finish\")\n            .setRequired(true)\n        )\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"home_score\")\n            .setDescription(\"Home team final score\")\n            .setRequired(true)\n            .setMinValue(0)\n        )\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"away_score\")\n            .setDescription(\"Away team final score\")\n            .setRequired(true)\n            .setMinValue(0)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only staff can finish matches.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const homeScore = interaction.options.getInteger(\"home_score\", true);\n    const awayScore = interaction.options.getInteger(\"away_score\", true);\n\n    try {\n      const match = await matchService.finishMatch(matchId, {\n        homeScore,\n        awayScore,\n      });\n\n      // ── Auto-post match result news ──\n      try {\n        const fullMatch = await prisma.match.findUnique({\n          where: { id: match.id },\n          include: {\n            homeTeam: true,\n            awayTeam: true,\n            goals: { include: { player: { include: { user: true } } } },\n            mvps: { include: { player: { include: { user: true } } } },\n          },\n        });\n\n        if (fullMatch && interaction.guild) {\n          const scorers = fullMatch.goals.map(\n            (g) => `${g.player.user.username}${g.minute ? ` (${g.minute}')` : \"\"}`\n          );\n          const mvp = fullMatch.mvps[0]?.player.user.username;\n\n          await newsService.announceMatchResult(\n            interaction.client as ExtendedClient,\n            {\n              guildId: interaction.guild.id,\n              homeTeam: fullMatch.homeTeam.name,\n              awayTeam: fullMatch.awayTeam.name,\n              homeScore: fullMatch.homeScore,\n              awayScore: fullMatch.awayScore,\n              scorers,\n              mvp,\n              matchId: match.id,\n            }\n          );\n\n          // Check milestones for all goal scorers and MVP\n          for (const g of fullMatch.goals) {\n            await newsService.checkMilestones(\n              interaction.client as ExtendedClient,\n              interaction.guild.id,\n              g.playerId\n            );\n          }\n          if (fullMatch.mvps[0]) {\n            await newsService.checkMilestones(\n              interaction.client as ExtendedClient,\n              interaction.guild.id,\n              fullMatch.mvps[0].playerId\n            );\n          }\n        }\n      } catch (newsError) {\n        console.error(\"[Match News Error]\", newsError);\n        // Non-fatal — match result is still saved\n      }\n\n      const winnerText =\n        homeScore > awayScore\n          ? \"🏠 **Home team wins!**\"\n          : awayScore > homeScore\n            ? \"🚗 **Away team wins!**\"\n            : \"🤝 **It's a draw!**\";\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"✅ Match Finished!\")\n        .setColor(\"#00AA00\")\n        .setDescription(\n          `**${match.homeTeamId}** ${match.homeScore} - ${match.awayScore} **${match.awayTeamId}**`\n        )\n        .addFields(\n          { name: \"📋 Result\", value: winnerText, inline: false },\n          { name: \"🔢 Match ID\", value: match.id.slice(0, 8), inline: true },\n          { name: \"📊 Status\", value: \"✅ Finished\", inline: true }\n        )\n        .setFooter({\n          text: \"Standings have been updated | Legacy Football Championship\",\n        })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Match Finish Error]\", error);\n      await interaction.editReply({\n        content: \"❌ Failed to finish the match. Check the match ID.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/news/setchannel.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  ChannelType,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News and media commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"setchannel\")\n        .setDescription(\"Set the news broadcast channel (Management only)\")\n        .addChannelOption((opt) =>\n          opt\n            .setName(\"channel\")\n            .setDescription(\"The text channel for news broadcasts\")\n            .setRequired(true)\n            .addChannelTypes(ChannelType.GuildText)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const channel = interaction.options.getChannel(\"channel\", true);\n    if (!interaction.guild) return;\n\n    await newsService.setNewsChannel(interaction.guild.id, channel.id);\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"📢 News Channel Configured!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `All auto-news will now be posted in ${channel}.`\n      )\n      .addFields(\n        { name: \"📺 Channel\", value: `${channel}`, inline: true },\n        {\n          name: \"📋 Auto-Posts Include\",\n          value: [\n            \"• ⚽ Match results & highlights\",\n            \"• 🔄 Transfer announcements\",\n            \"• 🏅 Award ceremonies\",\n            \"• 📅 Season start/end\",\n            \"• 🌟 Player milestones\",\n            \"• 📊 Weekly roundups\",\n            \"• 📢 Breaking broadcasts\",\n          ].join(\"\\n\"),\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • News System\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/news/latest.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst TYPE_EMOJIS: Record<string, string> = {\n  match_result: \"⚽\",\n  transfer: \"🔄\",\n  award: \"🏅\",\n  season_start: \"📅\",\n  season_end: \"🏆\",\n  milestone: \"🌟\",\n  broadcast: \"📢\",\n  weekly_roundup: \"📊\",\n};\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"latest\")\n        .setDescription(\"View the latest LFC news and announcements\")\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"count\")\n            .setDescription(\"Number of articles to show (1-20)\")\n            .setRequired(false)\n            .setMinValue(1)\n            .setMaxValue(20)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const count = interaction.options.getInteger(\"count\") ?? 5;\n    const guildId = interaction.guild?.id;\n    if (!guildId) return;\n\n    try {\n      const articles = await newsService.getRecentNews(guildId, count);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📰 Latest LFC News\")\n        .setColor(\"#00AA00\");\n\n      if (articles.length > 0) {\n        embed.setDescription(\n          articles\n            .map(\n              (a, i) =>\n                `${i + 1}. ${TYPE_EMOJIS[a.type] ?? \"📰\"} **${a.title}**\\n` +\n                `   ${a.content.slice(0, 100)}${a.content.length > 100 ? \"...\" : \"\"}\\n` +\n                `   🕐 <t:${Math.floor(a.createdAt.getTime() / 1000)}:R>`\n            )\n            .join(\"\\n\\n\")\n        );\n      } else {\n        embed.setDescription(\"No news articles yet. As matches happen, transfers complete, and awards are given, they'll appear here automatically!\");\n      }\n\n      embed\n        .setFooter({\n          text: `Showing last ${articles.length || 0} articles • Legacy Football Championship`,\n        })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[News Latest Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching news.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/news/broadcast.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"broadcast\")\n        .setDescription(\"Send a breaking news broadcast (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"title\")\n            .setDescription(\"Broadcast headline\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"message\")\n            .setDescription(\"Broadcast message content\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"color\")\n            .setDescription(\"Embed color (red, blue, green, gold)\")\n            .setRequired(false)\n            .addChoices(\n              { name: \"🔴 Red (Urgent)\", value: \"#FF0000\" },\n              { name: \"🔵 Blue (Info)\", value: \"#0066FF\" },\n              { name: \"🟢 Green (Positive)\", value: \"#00AA00\" },\n              { name: \"🟡 Gold (Important)\", value: \"#FFD700\" }\n            )\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can broadcast.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const title = interaction.options.getString(\"title\", true);\n    const message = interaction.options.getString(\"message\", true);\n    const color = interaction.options.getString(\"color\") ?? \"#FF0000\";\n\n    if (!interaction.guild?.id) return;\n\n    try {\n      const result = await newsService.announceBroadcast(\n        interaction.client as never,\n        {\n          guildId: interaction.guild.id,\n          title,\n          message,\n          authorName: interaction.user.username,\n          color,\n        }\n      );\n\n      if (result) {\n        await interaction.editReply({\n          content: `✅ Broadcast sent! [View message](${result.url})`,\n        });\n      } else {\n        await interaction.editReply({\n          content: \"⚠️ Broadcast published but no news channel is configured. Use `/news setchannel` first.\",\n        });\n      }\n    } catch (error) {\n      console.error(\"[Broadcast Error]\", error);\n      await interaction.editReply({\n        content: \"❌ Failed to send broadcast. Make sure a news channel is set via `/news setchannel`.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/news/roundup.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"roundup\")\n        .setDescription(\"Generate a weekly league roundup (Management only)\")\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const guildId = interaction.guild?.id;\n    if (!guildId) return;\n\n    try {\n      const activeSeason = await leagueService.getActiveSeason();\n      if (!activeSeason) {\n        await interaction.editReply({\n          content: \"❌ No active season to generate a roundup for.\",\n        });\n        return;\n      }\n\n      const standings = await leagueService.getStandings(activeSeason.id);\n      const topScorers = await playerService.getTopGoalscorers(5);\n      const results = await matchService.getRecentResults(5);\n\n      const result = await newsService.generateWeeklyRoundup(\n        interaction.client as never,\n        guildId,\n        activeSeason.name,\n        standings.map((s) => ({\n          position: s.position,\n          teamName: s.teamName,\n          played: s.played,\n          wins: s.wins,\n          draws: s.draws,\n          losses: s.losses,\n          points: s.points,\n        })),\n        topScorers.map((p) => ({\n          name: p.user.username,\n          goals: p.goals,\n          team: p.team?.name,\n        })),\n        results.map((m) => ({\n          homeTeam: m.homeTeam.name,\n          awayTeam: m.awayTeam.name,\n          homeScore: m.homeScore,\n          awayScore: m.awayScore,\n        }))\n      );\n\n      if (result) {\n        await interaction.editReply({\n          content: `✅ Weekly roundup published! [View post](${result.url})`,\n        });\n      } else {\n        await interaction.editReply({\n          content: \"⚠️ Roundup generated but no news channel is configured. Use `/news setchannel` first.\",\n        });\n      }\n    } catch (error) {\n      console.error(\"[Roundup Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while generating the roundup.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/player/profile.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { formatSeasonStats, formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"player\")\n    .setDescription(\"View a player's full profile\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"profile\")\n        .setDescription(\"View a player profile\")\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"The player to look up\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const targetUser = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n\n      if (!player) {\n        const embed = new EmbedBuilder()\n          .setTitle(\"❌ Player Not Found\")\n          .setDescription(\n            `${targetUser.username} is not registered as an LFC player yet. They need to play their first match to be registered.`\n          )\n          .setColor(\"#FF0000\")\n          .setTimestamp();\n\n        await interaction.editReply({ embeds: [embed] });\n        return;\n      }\n\n      // Season stats display\n      const seasonStatsText =\n        player.seasonStats.length > 0\n          ? player.seasonStats\n              .map(\n                (s) =>\n                  `**${s.season.name}**: ⚽ ${s.goals}G | 🎯 ${s.assists}A | 🏆 ${s.mvps} MVP | 📋 ${s.appearances} Apps`\n              )\n              .join(\"\\n\")\n          : \"No season data yet.\";\n\n      // Career stats\n      const careerStats = {\n        goals: player.goals,\n        assists: player.assists,\n        mvps: player.mvps,\n        appearances: player.appearances,\n        yellowCards: player.yellowCards,\n        redCards: player.redCards,\n      };\n\n      // Awards\n      const awardsText =\n        player.awards.length > 0\n          ? player.awards\n              .map((a) => `🏅 **${a.type}** — ${a.season.name}`)\n              .join(\"\\n\")\n          : \"No awards yet.\";\n\n      // Transfers\n      const transfers = await playerService.getTransferHistory(player.id);\n      const transfersText =\n        transfers.length > 0\n          ? transfers\n              .slice(0, 5)\n              .map(\n                (t) =>\n                  `🔄 ${t.fromTeamName ?? \"Free Agent\"} → ${t.toTeamName ?? \"Free Agent\"}${t.fee ? ` ($${t.fee}M)` : \"\"}`\n              )\n              .join(\"\\n\")\n          : \"No transfer history.\";\n\n      const embed = new EmbedBuilder()\n        .setTitle(`${targetUser.username} — LFC Profile`)\n        .setThumbnail(targetUser.displayAvatarURL())\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: \"👤 General\",\n            value: [\n              `**LFC ID:** ${player.lfcId}`,\n              `**Discord ID:** ${player.discordId}`,\n              `**Joined:** ${formatDate(player.joinedAt)}`,\n            ].join(\"\\n\"),\n            inline: false,\n          },\n          {\n            name: \"⚽ Club & Position\",\n            value: [\n              `**Club:** ${player.team?.name ?? \"Free Agent\"}`,\n              `**Position:** ${player.position}`,\n              `**Region:** ${player.region}`,\n            ].join(\"\\n\"),\n            inline: true,\n          },\n          {\n            name: \"🏆 Trophies & Awards\",\n            value: `**Trophies:** ${player.trophies}\\n${awardsText}`,\n            inline: true,\n          },\n          {\n            name: \"📊 Season Stats\",\n            value: seasonStatsText,\n            inline: false,\n          },\n          {\n            name: \"📈 Career Stats\",\n            value: formatSeasonStats(careerStats),\n            inline: false,\n          },\n          {\n            name: \"🔄 Transfer History\",\n            value: transfersText,\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Player Profile Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching the player profile.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/player/stats.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { formatSeasonStats } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"player\")\n    .setDescription(\"Player commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"stats\")\n        .setDescription(\"View a player's detailed career statistics\")\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"The player to view stats for\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const targetUser = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n\n      if (!player) {\n        await interaction.editReply({\n          content: `❌ ${targetUser.username} is not registered as an LFC player.`,\n        });\n        return;\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(`📊 ${targetUser.username} — Career Statistics`)\n        .setThumbnail(targetUser.displayAvatarURL())\n        .setColor(\"#00AA00\");\n\n      // Per-season breakdown\n      if (player.seasonStats.length > 0) {\n        for (const stat of player.seasonStats) {\n          embed.addFields({\n            name: `📅 ${stat.season.name}`,\n            value: formatSeasonStats({\n              goals: stat.goals,\n              assists: stat.assists,\n              mvps: stat.mvps,\n              appearances: stat.appearances,\n              yellowCards: stat.yellowCards,\n              redCards: stat.redCards,\n            }),\n            inline: true,\n          });\n        }\n      } else {\n        embed.addFields({\n          name: \"No Season Data\",\n          value: \"This player hasn't recorded any stats yet.\",\n          inline: false,\n        });\n      }\n\n      // Career totals\n      embed.addFields({\n        name: \"🏆 Career Totals\",\n        value: formatSeasonStats({\n          goals: player.goals,\n          assists: player.assists,\n          mvps: player.mvps,\n          appearances: player.appearances,\n          yellowCards: player.yellowCards,\n          redCards: player.redCards,\n        }),\n        inline: false,\n      });\n\n      embed.setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Player Stats Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching player stats.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/player/leaderboard.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  StringSelectMenuBuilder,\n  ComponentType,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst LEADERBOARD_TYPES = [\n  { label: \"⚽ Top Goalscorers\", value: \"goals\", emoji: \"⚽\" },\n  { label: \"🎯 Top Assists\", value: \"assists\", emoji: \"🎯\" },\n  { label: \"🏆 Most MVPs\", value: \"mvps\", emoji: \"🏆\" },\n  { label: \"📋 Most Appearances\", value: \"appearances\", emoji: \"📋\" },\n] as const;\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"leaderboard\")\n    .setDescription(\"View league leaderboards\")\n    .addStringOption((opt) =>\n      opt\n        .setName(\"type\")\n        .setDescription(\"Leaderboard category\")\n        .setRequired(false)\n        .addChoices(\n          { name: \"⚽ Top Goalscorers\", value: \"goals\" },\n          { name: \"🎯 Top Assists\", value: \"assists\" },\n          { name: \"🏆 Most MVPs\", value: \"mvps\" },\n          { name: \"📋 Most Appearances\", value: \"appearances\" }\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const selectedType = interaction.options.getString(\"type\") ?? \"goals\";\n\n    try {\n      await showLeaderboard(interaction, selectedType);\n    } catch (error) {\n      console.error(\"[Leaderboard Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching the leaderboard.\",\n      });\n    }\n  },\n};\n\nasync function showLeaderboard(\n  interaction: CommandInteraction,\n  type: string\n) {\n  let players: Array<{\n    user: { username: string; globalName: string | null };\n    team: { name: string } | null;\n    goals: number;\n    assists: number;\n    mvps: number;\n    appearances: number;\n  }>;\n  let title: string;\n  let valueKey: string;\n\n  switch (type) {\n    case \"assists\":\n      players = await playerService.getTopAssists();\n      title = \"🎯 Top Assists\";\n      valueKey = \"assists\";\n      break;\n    case \"mvps\":\n      players = await playerService.getTopMvps();\n      title = \"🏆 Most MVPs\";\n      valueKey = \"mvps\";\n      break;\n    case \"appearances\":\n      players = await playerService.getTopAppearances();\n      title = \"📋 Most Appearances\";\n      valueKey = \"appearances\";\n      break;\n    default:\n      players = await playerService.getTopGoalscorers();\n      title = \"⚽ Top Goalscorers\";\n      valueKey = \"goals\";\n  }\n\n  const embed = new EmbedBuilder()\n    .setTitle(title)\n    .setColor(\"#00AA00\")\n    .setDescription(\n      players.length > 0\n        ? players\n            .map(\n              (p, i) =>\n                `${i + 1}. **${p.user.globalName ?? p.user.username}**` +\n                `${p.team ? ` (${p.team.name})` : \"\"} — **${(p as Record<string, number>)[valueKey]}**`\n            )\n            .join(\"\\n\")\n        : \"No data available yet.\"\n    )\n    .setFooter({ text: \"Legacy Football Championship\" })\n    .setTimestamp();\n\n  // Add a select menu to switch leaderboard types\n  const select = new StringSelectMenuBuilder()\n    .setCustomId(\"leaderboard_select\")\n    .setPlaceholder(\"Switch leaderboard...\")\n    .addOptions(\n      LEADERBOARD_TYPES.map((lt) => ({\n        label: lt.label,\n        value: lt.value,\n      }))\n    );\n\n  const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(\n    select\n  );\n\n  const reply = await interaction.editReply({\n    embeds: [embed],\n    components: [row],\n  });\n\n  // Handle select menu interaction\n  const collector = reply.createMessageComponentCollector({\n    componentType: ComponentType.StringSelect,\n    time: 60_000,\n  });\n\n  collector.on(\"collect\", async (selectInteraction) => {\n    if (selectInteraction.user.id !== interaction.user.id) {\n      await selectInteraction.reply({\n        content: \"❌ Only the command author can use this.\",\n        ephemeral: true,\n      });\n      return;\n    }\n\n    await selectInteraction.deferUpdate();\n    await showLeaderboard(\n      selectInteraction as unknown as CommandInteraction,\n      selectInteraction.values[0]\n    );\n  });\n\n  collector.on(\"end\", async () => {\n    const disabledRow =\n      ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n    disabledRow.components.forEach((c) => c.setDisabled(true));\n\n    await interaction.editReply({ components: [disabledRow] });\n  });\n}\n\nexport default command;","src/commands/team/create.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"create\")\n        .setDescription(\"Create a new team (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Full team name (e.g. Legacy FC)\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"short\")\n            .setDescription(\"Short name (e.g. LFC)\")\n            .setRequired(false)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"description\")\n            .setDescription(\"Team description\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    // Permission check\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need the **Founder** or **League Management** role to create teams.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const name = interaction.options.getString(\"name\", true);\n    const shortName = interaction.options.getString(\"short\");\n    const description = interaction.options.getString(\"description\");\n    const managerId = interaction.user.id;\n\n    try {\n      // Ensure user exists in DB\n      await playerService.getOrCreatePlayer(managerId, interaction.user.username);\n\n      // Check if team name is taken\n      const existing = await teamService.getTeamByName(name);\n      if (existing) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Team Already Exists\",\n              `A team named **${name}** already exists.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      const team = await teamService.createTeam({\n        name,\n        shortName: shortName ?? undefined,\n        description: description ?? undefined,\n        managerId,\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(`✅ Team Created: ${team.name}`)\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"📛 Name\", value: team.name, inline: true },\n          {\n            name: \"🔤 Short Name\",\n            value: team.shortName ?? \"None\",\n            inline: true,\n          },\n          {\n            name: \"👤 Manager\",\n            value: `<@${team.manager.discordId}>`,\n            inline: true,\n          },\n          {\n            name: \"📝 Description\",\n            value: team.description ?? \"No description.\",\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Create Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while creating the team.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/team/info.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"info\")\n        .setDescription(\"View team information\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Team name\")\n            .setRequired(true)\n            .setAutocomplete(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"name\", true);\n\n    try {\n      const team = await teamService.getTeamByName(teamName);\n\n      if (!team) {\n        await interaction.editReply({\n          content: `❌ Team **${teamName}** not found.`,\n        });\n        return;\n      }\n\n      // Get current season stats\n      const seasonStats = team.seasonTeams[team.seasonTeams.length - 1];\n\n      const embed = new EmbedBuilder()\n        .setTitle(`🏟️ ${team.name} ${team.shortName ? `(${team.shortName})` : \"\"}`)\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: \"👤 Manager\",\n            value: `<@${team.manager.discordId}>`,\n            inline: true,\n          },\n          {\n            name: \"👥 Squad Size\",\n            value: `${team.players.length} players`,\n            inline: true,\n          },\n          {\n            name: \"🏆 Trophies\",\n            value: `${team.trophies}`,\n            inline: true,\n          },\n          {\n            name: \"📝 Description\",\n            value: team.description ?? \"No description set.\",\n            inline: false,\n          }\n        );\n\n      // Add season stats if available\n      if (seasonStats) {\n        embed.addFields({\n          name: `📊 Season Record (${seasonStats.season?.name ?? \"Current\"})`,\n          value: [\n            `**Played:** ${seasonStats.played}`,\n            `**Wins:** ${seasonStats.wins}`,\n            `**Draws:** ${seasonStats.draws}`,\n            `**Losses:** ${seasonStats.losses}`,\n            `**Goals For:** ${seasonStats.goalsFor}`,\n            `**Goals Against:** ${seasonStats.goalsAgainst}`,\n            `**GD:** ${seasonStats.goalsFor - seasonStats.goalsAgainst}`,\n            `**Points:** ${seasonStats.points}`,\n          ].join(\" | \"),\n          inline: false,\n        });\n      }\n\n      // Top 5 players by goals\n      const topScorers = [...team.players]\n        .sort((a, b) => b.goals - a.goals)\n        .slice(0, 5);\n\n      if (topScorers.length > 0) {\n        embed.addFields({\n          name: \"⚽ Top Scorers\",\n          value: topScorers\n            .map(\n              (p, i) =>\n                `${i + 1}. **${p.user.username}** — ${p.goals}G / ${p.assists}A`\n            )\n            .join(\"\\n\"),\n          inline: false,\n        });\n      }\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Info Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching team info.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/team/roster.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport type { Command } from \"../../types/index.js\";\nimport type { Position } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"roster\")\n        .setDescription(\"View a team's full roster\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Team name\")\n            .setRequired(true)\n            .setAutocomplete(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"name\", true);\n\n    try {\n      const team = await teamService.getTeamByName(teamName);\n\n      if (!team) {\n        await interaction.editReply({\n          content: `❌ Team **${teamName}** not found.`,\n        });\n        return;\n      }\n\n      const positions: Position[] = [\n        \"Goalkeeper\",\n        \"Defender\",\n        \"Midfielder\",\n        \"Forward\",\n      ];\n\n      const embed = new EmbedBuilder()\n        .setTitle(`👥 ${team.name} — Squad Roster`)\n        .setColor(\"#00AA00\");\n\n      let totalPlayers = 0;\n\n      for (const pos of positions) {\n        const positionPlayers = team.players.filter(\n          (p) => p.position === pos\n        );\n\n        if (positionPlayers.length > 0) {\n          totalPlayers += positionPlayers.length;\n          embed.addFields({\n            name: `${getPositionEmoji(pos)} ${pos}s (${positionPlayers.length})`,\n            value: positionPlayers\n              .map(\n                (p) =>\n                  `**${p.user.username}** — ⚽ ${p.goals}G / 🎯 ${p.assists}A / 🏆 ${p.mvps} MVP`\n              )\n              .join(\"\\n\"),\n            inline: false,\n          });\n        } else {\n          embed.addFields({\n            name: `${getPositionEmoji(pos)} ${pos}s`,\n            value: \"No players\",\n            inline: true,\n          });\n        }\n      }\n\n      embed.setFooter({\n        text: `Total: ${totalPlayers} players | Legacy Football Championship`,\n      });\n      embed.setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Roster Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching the roster.\",\n      });\n    }\n  },\n};\n\nfunction getPositionEmoji(position: Position): string {\n  switch (position) {\n    case \"Goalkeeper\":\n      return \"🧤\";\n    case \"Defender\":\n      return \"🛡️\";\n    case \"Midfielder\":\n      return \"🎯\";\n    case \"Forward\":\n      return \"⚽\";\n    default:\n      return \"👤\";\n  }\n}\n\nexport default command;","src/commands/team/stats.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"stats\")\n        .setDescription(\"View detailed team statistics\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Team name\")\n            .setRequired(true)\n            .setAutocomplete(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"name\", true);\n\n    try {\n      const team = await teamService.getTeamByName(teamName);\n\n      if (!team) {\n        await interaction.editReply({\n          content: `❌ Team **${teamName}** not found.`,\n        });\n        return;\n      }\n\n      const activeSeason = await leagueService.getActiveSeason();\n\n      const embed = new EmbedBuilder()\n        .setTitle(`📊 ${team.name} — Statistics`)\n        .setColor(\"#00AA00\");\n\n      // Season-by-season breakdown\n      if (team.seasonTeams.length > 0) {\n        for (const stat of team.seasonTeams) {\n          const gd = stat.goalsFor - stat.goalsAgainst;\n          const gdText = gd >= 0 ? `+${gd}` : `${gd}`;\n          embed.addFields({\n            name: `📅 ${stat.season?.name ?? \"Unknown Season\"}`,\n            value: [\n              `**Played:** ${stat.played}`,\n              `**Wins:** ${stat.wins}`,\n              `**Draws:** ${stat.draws}`,\n              `**Losses:** ${stat.losses}`,\n              `**GF:** ${stat.goalsFor} | **GA:** ${stat.goalsAgainst} | **GD:** ${gdText}`,\n              `**Points:** ${stat.points} (${((stat.points / (stat.played * 3)) * 100).toFixed(1)}% win rate)`,\n            ].join(\"\\n\"),\n            inline: true,\n          });\n        }\n      } else {\n        embed.addFields({\n          name: \"No Season Data\",\n          value: \"This team hasn't played any matches yet.\",\n          inline: false,\n        });\n      }\n\n      // Player contributions\n      const topScorer = [...team.players].sort((a, b) => b.goals - a.goals)[0];\n      const topAssist = [...team.players].sort(\n        (a, b) => b.assists - a.assists\n      )[0];\n      const topMvp = [...team.players].sort((a, b) => b.mvps - a.mvps)[0];\n\n      embed.addFields({\n        name: \"🌟 Key Players\",\n        value: [\n          `⚽ **Top Scorer:** ${topScorer ? `${topScorer.user.username} (${topScorer.goals}G)` : \"N/A\"}`,\n          `🎯 **Top Assists:** ${topAssist ? `${topAssist.user.username} (${topAssist.assists}A)` : \"N/A\"}`,\n          `🏆 **Most MVPs:** ${topMvp ? `${topMvp.user.username} (${topMvp.mvps})` : \"N/A\"}`,\n        ].join(\"\\n\"),\n        inline: false,\n      });\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Stats Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching team stats.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/transfer/create.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"transfer\")\n    .setDescription(\"Transfer management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"create\")\n        .setDescription(\"Create a transfer request (Management only)\")\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"Player to transfer\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"to_team\")\n            .setDescription(\"Destination team\")\n            .setRequired(true)\n        )\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"fee\")\n            .setDescription(\"Transfer fee (in millions)\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can create transfers.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"player\", true);\n    const toTeamName = interaction.options.getString(\"to_team\", true);\n    const fee = interaction.options.getInteger(\"fee\");\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n      if (!player) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Player Not Found\", `${targetUser.username} is not registered.`)],\n        });\n        return;\n      }\n\n      const toTeam = await teamService.getTeamByName(toTeamName);\n      if (!toTeam) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Team Not Found\", `Team **${toTeamName}** not found.`)],\n        });\n        return;\n      }\n\n      const transfer = await prisma.transfer.create({\n        data: {\n          playerId: player.id,\n          fromTeamId: player.teamId,\n          fromTeamName: player.team?.name ?? \"Free Agent\",\n          toTeamId: toTeam.id,\n          toTeamName: toTeam.name,\n          fee,\n          status: \"Pending\",\n        },\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🔄 Transfer Request Created\")\n        .setColor(\"#FFAA00\")\n        .addFields(\n          { name: \"👤 Player\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"➡️ Destination\", value: toTeam.name, inline: true },\n          { name: \"💰 Fee\", value: fee ? `$${fee}M` : \"Free Transfer\", inline: true },\n          { name: \"📋 Status\", value: \"⏳ Pending\", inline: true },\n          { name: \"🔢 Transfer ID\", value: transfer.id.slice(0, 8), inline: true }\n        )\n        .setFooter({ text: \"Use /transfer complete to finalize\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Transfer Create Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while creating the transfer.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/transfer/complete.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"transfer\")\n    .setDescription(\"Transfer commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"complete\")\n        .setDescription(\"Complete a pending transfer\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"transfer_id\")\n            .setDescription(\"Transfer ID to complete\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can complete transfers.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const transferId = interaction.options.getString(\"transfer_id\", true);\n\n    try {\n      const transfer = await prisma.transfer.findUnique({\n        where: { id: transferId },\n        include: { player: { include: { user: true } } },\n      });\n\n      if (!transfer) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Transfer Not Found\", `Transfer ID **${transferId}** not found.`)],\n        });\n        return;\n      }\n\n      if (transfer.status !== \"Pending\") {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Invalid Status\", `This transfer is already **${transfer.status}**.`)],\n        });\n        return;\n      }\n\n      // Update the player's team\n      if (transfer.toTeamId) {\n        await teamService.addPlayerToTeam(transfer.playerId, transfer.toTeamId);\n      } else {\n        await teamService.removePlayerFromTeam(transfer.playerId);\n      }\n\n      // Mark transfer as completed\n      await prisma.transfer.update({\n        where: { id: transferId },\n        data: {\n          status: \"Completed\",\n          completedAt: new Date(),\n        },\n      });\n\n      // ── Auto-post transfer news ──\n      try {\n        if (interaction.guild) {\n          await newsService.announceTransfer(\n            interaction.client as ExtendedClient,\n            {\n              guildId: interaction.guild.id,\n              playerName: transfer.player.user.username,\n              fromTeam: transfer.fromTeamName ?? \"Free Agent\",\n              toTeam: transfer.toTeamName ?? \"Free Agent\",\n              fee: transfer.fee ? `$${transfer.fee}M` : undefined,\n            }\n          );\n        }\n      } catch (newsError) {\n        console.error(\"[Transfer News Error]\", newsError);\n        // Non-fatal\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"✅ Transfer Completed!\")\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"👤 Player\", value: transfer.player.user.username, inline: true },\n          { name: \"➡️ From\", value: transfer.fromTeamName ?? \"Free Agent\", inline: true },\n          { name: \"🏠 To\", value: transfer.toTeamName ?? \"Free Agent\", inline: true },\n          { name: \"💰 Fee\", value: transfer.fee ? `$${transfer.fee}M` : \"Free Transfer\", inline: true }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Transfer Complete Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while completing the transfer.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/transfer/list.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"transfers\")\n    .setDescription(\"View recent completed transfers\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const transfers = await prisma.transfer.findMany({\n        where: { status: \"Completed\" },\n        include: {\n          player: { include: { user: true } },\n        },\n        orderBy: { completedAt: \"desc\" },\n        take: 10,\n      });\n\n      if (transfers.length === 0) {\n        await interaction.editReply({\n          content: \"📋 No completed transfers yet.\",\n        });\n        return;\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🔄 Recent Transfers\")\n        .setColor(\"#00AA00\")\n        .setDescription(\n          transfers\n            .map(\n              (t, i) =>\n                `${i + 1}. **${t.player.user.username}**` +\n                `: ${t.fromTeamName ?? \"Free Agent\"} → ${t.toTeamName ?? \"Free Agent\"}` +\n                (t.fee ? ` ($${t.fee}M)` : \" (Free)\")\n            )\n            .join(\"\\n\")\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Transfers List Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching transfers.\",\n      });\n    }\n  },\n};\n\nexport default command;"};
